// Pseudocode: redaction + toxicity routing
function processMessage(msg) {
  // Stage 1: PII redaction
  const redacted = redactPII(msg.text);

  // Stage 2: Toxicity classification
  const prediction = await classifier.predict(redacted);

  // Stage 3: Policy gate routing
  if (prediction.score > HIGH_RISK_THRESHOLD) {
    queueForHumanReview({ ...msg, redactedText: redacted, prediction });
  } else {
    publishMessage({ ...msg, redactedText: redacted, prediction });
  }
}
```

